tests.executable:
from httpbin.core import app
client = app.test_client()

def test_delete_files_field_is_empty_dict_when_no_file_uploaded():
    r = client.delete('/delete')
    assert r.status_code == 200
    body = r.get_json()
    assert body['files'] == {}
    assert body['form'] == {}

test_delete_files_field_is_empty_dict_when_no_file_uploaded()
